{
  "handle_internally": [
    {
      "evidence": [
        "E01"
      ],
      "match": {
        "categories": [
          "quantity"
        ],
        "keywords": [
          "open",
          "outline"
        ],
        "scenarios": [
          "design"
        ],
        "severities": []
      },
      "name": "Open drawing outlines",
      "why": "The firm confirms open outlines in the CAD on its own side; the developer does not need to hear about line work."
    },
    {
      "evidence": [
        "E16"
      ],
      "match": {
        "categories": [
          "scale"
        ],
        "keywords": [
          "scale"
        ],
        "scenarios": [
          "design"
        ],
        "severities": []
      },
      "name": "Title-block scale discrepancies",
      "why": "The firm measures off the scale bar itself; a wrong title-block scale is not worth the developer's time."
    },
    {
      "evidence": [
        "E18"
      ],
      "match": {
        "categories": [
          "bill"
        ],
        "keywords": [
          "aligned"
        ],
        "scenarios": [
          "quote"
        ],
        "severities": []
      },
      "name": "Bill spelling or item alignment",
      "why": "A misspelt row does not change the price, and the firm never raises spelling."
    },
    {
      "evidence": [
        "E23"
      ],
      "match": {
        "categories": [
          "bill"
        ],
        "keywords": [
          "hidden",
          "sheet",
          "old"
        ],
        "scenarios": [
          "quote"
        ],
        "severities": []
      },
      "name": "Hidden or old bill sheets",
      "why": "Hidden or old sheets are the developer's housekeeping, not worth a line in the email."
    }
  ],
  "pricing": {
    "basis": "The firm's own installed list range, with 12 months of maintenance included.",
    "conventions": [
      "Quote the firm's own installed range, never the developer's number.",
      "The governing drawing controls quantities; bill quantities that differ from it are reduced or corrected to the drawn quantity.",
      "Hedges are priced per plant, never per metre.",
      "A rate more than 15% outside the firm's list is queried; a rate inside 15% is let go.",
      "Arithmetic is addressed first among the money points because it moves the developer's total."
    ],
    "evidence": [
      "E19",
      "E20",
      "E02.2",
      "E17",
      "E21"
    ],
    "tolerance_pct": 15
  },
  "reply": {
    "closing": "",
    "evidence": [
      "E19",
      "E21",
      "E29",
      "E02.2",
      "E18"
    ],
    "greeting": "",
    "opening": "",
    "rules": [
      "Be polite when querying a price and quote the firm's own range rather than the developer's number.",
      "For arithmetic, ask politely to 'please check the subtotal' and never use the word 'error'.",
      "For quantity differences, give both the bill and drawing numbers.",
      "Never raise spelling.",
      "Keep the email short."
    ],
    "sign_off": "the estimating team",
    "tone": "polite, short"
  },
  "send_back": [
    {
      "evidence": [
        "E09"
      ],
      "match": {
        "categories": [
          "regulation"
        ],
        "keywords": [
          "fire",
          "lane"
        ],
        "scenarios": [
          "regulation"
        ],
        "severities": []
      },
      "name": "Tree blocking fire truck access",
      "why": "Fire lane comes first, before any money, because the permit fails without it; ask them to move the tree out of the lane."
    },
    {
      "evidence": [
        "E14"
      ],
      "match": {
        "categories": [
          "regulation"
        ],
        "keywords": [
          "greening"
        ],
        "scenarios": [
          "regulation"
        ],
        "severities": [
          "fail"
        ]
      },
      "name": "Greening requirement failure",
      "why": "A greening fail goes near the top; offer the cheapest fix that passes rather than more trees."
    },
    {
      "evidence": [
        "E15"
      ],
      "match": {
        "categories": [
          "protected_tree"
        ],
        "keywords": [
          "protected",
          "removed"
        ],
        "scenarios": [
          "regulation"
        ],
        "severities": []
      },
      "name": "Possible protected tree removal",
      "why": "The firm never prices a tree removal without the city's tree survey and asks for that survey."
    },
    {
      "evidence": [
        "E12"
      ],
      "match": {
        "categories": [
          "regulation"
        ],
        "keywords": [
          "tree",
          "pit",
          "artificial"
        ],
        "scenarios": [
          "regulation"
        ],
        "severities": []
      },
      "name": "Tree pit on artificial ground",
      "why": "On slabs and roofs the firm proposes shallow-rooted planting rather than more soil, so the pit rule and its effect on the greening count must be raised."
    },
    {
      "evidence": [
        "E29"
      ],
      "match": {
        "categories": [
          "sheet"
        ],
        "keywords": [
          "index",
          "package"
        ],
        "scenarios": [
          "design"
        ],
        "severities": []
      },
      "name": "Missing indexed sheet",
      "why": "The firm asks for every sheet listed on the index before it prices."
    },
    {
      "evidence": [
        "E21"
      ],
      "match": {
        "categories": [
          "arithmetic"
        ],
        "keywords": [
          "subtotal"
        ],
        "scenarios": [
          "quote"
        ],
        "severities": []
      },
      "name": "Bill arithmetic",
      "why": "Arithmetic always comes first among the money points because it moves the developer's total."
    },
    {
      "evidence": [
        "E02.2",
        "E22.2"
      ],
      "match": {
        "categories": [
          "quantity"
        ],
        "keywords": [],
        "scenarios": [
          "quote"
        ],
        "severities": []
      },
      "name": "Bill quantity differs from drawing",
      "why": "A bill quantity that differs from the governing drawing always goes back, with both numbers given."
    },
    {
      "evidence": [
        "E13"
      ],
      "match": {
        "categories": [
          "quantity"
        ],
        "keywords": [
          "azalea",
          "per"
        ],
        "scenarios": [
          "quote"
        ],
        "severities": []
      },
      "name": "Planting density below schedule",
      "why": "Ask for the density stated in the schedule, such as 4 plants per m², rather than the lower billed quantity."
    },
    {
      "evidence": [
        "E17"
      ],
      "match": {
        "categories": [
          "units"
        ],
        "keywords": [
          "hedge",
          "billed",
          "drawn"
        ],
        "scenarios": [
          "quote"
        ],
        "severities": []
      },
      "name": "Hedge billing unit mismatch",
      "why": "The firm prices hedges per plant, never per metre, in line with the procurement standard."
    },
    {
      "evidence": [
        "E19",
        "E20"
      ],
      "match": {
        "categories": [
          "price"
        ],
        "keywords": [],
        "scenarios": [
          "quote"
        ],
        "severities": []
      },
      "name": "Unit rate outside the firm's list",
      "why": "A rate more than 15% outside the firm's installed list gets queried, whether it is under or over the list."
    }
  ],
  "species_substitutions": [
    {
      "evidence": [
        "E13"
      ],
      "from": "azalea",
      "to": "Rhododendron simsii",
      "when": "Where the specification only says azalea; it is the native azalea."
    },
    {
      "evidence": [
        "E17"
      ],
      "from": "Duranta",
      "to": "Chinese ixora",
      "when": "If Duranta is short at the nursery, at the same spacing."
    },
    {
      "evidence": [
        "E12"
      ],
      "from": "large trees on artificial ground",
      "to": "Chinese ixora in planters",
      "when": "On slabs and roofs, as shallow-rooted planting in planters with less than 0.45 m of soil rather than adding more soil."
    }
  ],
  "summary": "The firm sends back permit-blocking regulation problems and missing information before money, then arithmetic, quantity, unit and price issues measured against the governing drawing, schedules and its own installed list. It handles drawing-production details, scale-bar measurement, spelling and workbook housekeeping internally, keeps the email short and polite, and favours practical planting substitutions over more expensive soil or tree additions."
}
